var EXTRA=[{dot:"gray",j:"Journal of Robotic Surgery",h:"Robot e sensore di pressione non battono la tecnica standard nella protesi",v:"Coorte retrospettiva che confronta strumentazione convenzionale, assistenza robotica MAKO e guida a sensore di pressione Verasense nella protesi con conservazione del crociato: nessuna differenza solida dopo la correzione statistica per i confronti multipli.",pmid:'42742643',doi:'10.1007/s11701-026-03954-w',temi:["protesi robotica","VELYS","tecnologia intraoperatoria"]},{dot:"gray",j:"The Knee",h:"Il testosterone in terapia sostitutiva e le complicanze della protesi",v:"Meta-analisi di quattro coorti appaiate: nessun aumento del rischio tromboembolico precoce, ma più infezioni periprotesiche e reinterventi a lungo termine nei pazienti in terapia sostitutiva con testosterone.",pmid:'42743767',doi:'10.1016/j.knee.2026.104637',temi:["protesi totale","farmacologia perioperatoria","infezione"]},{dot:"gray",j:"The Journal of Arthroplasty",h:"L'età biologica, non quella anagrafica, prevede il rischio della protesi",v:"Coorte giapponese: un indice di invecchiamento biologico calcolato da nove biomarcatori ematici predice meglio dell'età anagrafica il rischio perioperatorio e il recupero funzionale dopo protesi totale.",pmid:'42744006',doi:'10.1016/j.arth.2026.08.068',temi:["protesi totale","stratificazione del rischio","biomarcatori"]},{dot:"gray",j:"Journal of Clinical Medicine",h:"Un nuovo segno alla risonanza per distinguere le lesioni parziali del crociato",v:"Rassegna con studio pilota preliminare: il «segno del Namaste» sul piano coronale aiuterebbe a distinguere lesioni parziali e complete del LCA, ma serve conferma con un riferimento artroscopico su casistiche più ampie.",pmid:'42739704',doi:'10.3390/jcm15176699',temi:["lca","imaging","diagnostica"]},{dot:"gray",j:"The Knee",h:"Un nuovo strumento misura lo spessore della cartilagine in sala durante la protesi",v:"Descrizione tecnica di una sonda calibrata per stimare lo spessore cartilagineo residuo sul condilo femorale posteriore non usurato, utile nella protesi ad allineamento cinematico quando il condilo opposto è usurato.",pmid:'42743766',doi:'10.1016/j.knee.2026.104641',temi:["protesi totale","allineamento cinematico","strumentazione chirurgica"]},{dot:"gray",j:"The Knee",h:"Un nuovo disegno di componente femorale per popolazioni asiatiche ed europee",v:"Studio multicentrico su un impianto di protesi totale con opzione mediolaterale aggiuntiva, pensato per ridurre lo sporgere del componente femorale in popolazioni non caucasiche: sopravvivenza incoraggiante nel medio termine, non è la piattaforma che usi tu.",pmid:'42743765',doi:'10.1016/j.knee.2026.104638',temi:["protesi totale","design implantare","popolazioni diverse"]},{dot:"gray",j:"Journal of Imaging Informatics in Medicine",h:"Un algoritmo legge l'osteoporosi da una radiografia di ginocchio di routine",v:"Rete neurale che combina texture ossea e attenzione incrociata per segnalare un sospetto di osteoporosi da una radiografia di ginocchio già fatta per altri motivi: un possibile screening opportunistico, ancora in fase di sviluppo tecnico.",pmid:'42736491',doi:'10.1007/s10278-026-02276-5',temi:["intelligenza artificiale","osteoporosi","imaging"]},{dot:"gray",j:"Journal of Surgical Case Reports",h:"Un'avulsione ossea del collaterale laterale in un paziente pediatrico",v:"Caso clinico isolato di un distacco osseo del legamento collaterale laterale in un ginocchio ancora in crescita: un promemoria a considerare le lesioni legamentose periferiche anche fuori dal crociato nel trauma del ginocchio dell'adolescente.",pmid:'42741402',doi:'10.1093/jscr/rjag790',temi:["lcl","traumatologia pediatrica","caso clinico"]},{dot:"gray",j:"Osteoarthritis and Cartilage Open",h:"Un tutore in valgo sposta il carico lontano dal danno cartilagineo",v:"Studio di meccanica articolare: un tutore che impone un lieve valgo allontana il punto di contatto cartilagineo dalle lesioni ossee e condrali nel ginocchio varo con artrosi mediale, un'opzione non chirurgica da conoscere prima di proporre un'osteotomia.",pmid:'42741597',doi:'10.1016/j.ocarto.2026.100871',temi:["gonartrosi","ortesi","biomeccanica"]},{dot:"gray",j:"Journal of Clinical Medicine",h:"Allineamento funzionale o meccanico: il bilanciamento legamentoso non cambia granché",v:"Studio monocentrico sui fenotipi CPAK: il bilanciamento mediale e laterale ottenuto con l'allineamento funzionale non differisce sostanzialmente da quello simulato meccanico nella protesi totale, indipendentemente dal fenotipo costituzionale del ginocchio.",pmid:'42739815',doi:'10.3390/jcm15176812',temi:["protesi totale","allineamento funzionale","CPAK"]},{dot:"gray",j:"Journal of Clinical Medicine",h:"La protesi robotica ad allineamento funzionale rispetta la morfologia femorale nativa",v:"Serie ampia di protesi con sistema robotico senza immagini (ROSA, diverso da VELYS): la filosofia di allineamento funzionale non altera in modo rilevante offset e dimensione sagittale del femore distale, pur correggendo l'asse coronale in modo personalizzato.",pmid:'42739567',doi:'10.3390/jcm15176561',temi:["protesi robotica","allineamento funzionale","morfologia femorale"]}];
var SCOPERTE=[{t:"L'agopuntura auricolare riduce dolore e sintomi depressivi nell'artrosi di ginocchio dell'anziana",v:"Trial randomizzato controllato su 100 donne over 60 con gonartrosi cronica: dieci settimane di agopuntura auricolare settimanale riducono il dolore e i sintomi depressivi e migliorano l'autonomia nelle attività di base, rispetto a una stimolazione simulata su un punto neutro, senza eventi avversi registrati. Una tecnica di origine orientale testata con gli strumenti della medicina occidentale su una popolazione — donne anziane fragili — raramente al centro della ricerca ortopedica: un singolo trial monocentrico brasiliano, con oltre un terzo dei partecipanti perso al follow-up, da leggere come segnale e non come evidenza definitiva.",pmid:'42711151',doi:'10.1016/j.pmn.2026.07.025',temi:["medicina orientale","gonartrosi","agopuntura"]},{t:"Vent'anni di intelligenza artificiale nell'artrosi di ginocchio, in una mappa sola",v:"Un'analisi bibliometrica di 663 pubblicazioni dal 2004 a oggi mostra la traiettoria dell'intelligenza artificiale applicata all'artrosi di ginocchio: da un'esplorazione algoritmica (deep learning, radiomica) verso un uso via via più clinico — modelli predittivi, imaging, supporto alla decisione nella protesi. La Cina guida per numero di lavori, gli Stati Uniti per citazioni, ma la collaborazione fra le tre grandi aree del mondo resta limitata. Un promemoria di dove sta andando il campo nel suo insieme, non un singolo studio da applicare in ambulatorio.",pmid:'42718991',doi:'10.1177/20552076261486794',temi:["intelligenza artificiale","gonartrosi","bibliometria"]},{t:"Un modello matematico stima in pochi secondi la meccanica di un ginocchio mai visto prima",v:"Bioingegneria computazionale: partendo da centinaia di ginocchia sane segmentate automaticamente e simulate con elementi finiti durante il cammino, una rete neurale ricorrente impara a predire in pochi secondi decine di parametri di carico e contatto articolare da sole misure anatomiche, al posto di ore di simulazione. Ricerca ancora di base, lontana dall'uso clinico diretto, ma la direzione — sostituire la simulazione lenta con una stima immediata e specifica del paziente — è quella su cui si giocherà la pianificazione personalizzata di domani.",pmid:'42693750',doi:'10.1080/10255842.2026.2724359',temi:["bioingegneria","intelligenza artificiale","biomeccanica computazionale"]}];
var SOC={"1": {"video": "Uno studio su oltre 600 pazienti operati di protesi parziale di ginocchio confronta un impianto pianificato su misura per il singolo paziente con un impianto di serie standard. A due anni, i risultati percepiti dai pazienti sono simili nei due gruppi, ma l'impianto su misura si è dovuto sostituire più spesso, soprattutto perché si è allentato dall'osso. È uno studio di un solo centro, non un confronto randomizzato: un motivo in più per chiedere sempre l'evidenza clinica dietro una tecnologia presentata come più avanzata, prima di considerarla automaticamente migliore."}, "2": {"video": "Una revisione di 41 studi scientifici mette a confronto tre modi di riparare un danno alla cartilagine del ginocchio: il tritato di cartilagine prelevata dallo stesso paziente, la microfrattura e l'impianto di cellule cartilaginee coltivate in laboratorio. I risultati clinici sono simili, e il tritato ha avuto meno fallimenti nel periodo osservato. Il tritato di cartilagine è stato seguito per meno tempo delle altre due tecniche: il giudizio a lungo termine resta da confermare."}, "3": {"video": "Una revisione di 47 studi scientifici confronta diversi tipi di innesto usati per ricostruire il legamento crociato anteriore, misurando quanto bene i pazienti tornano a saltare. Il tendine quadricipitale — l'innesto più usato oggi in molti centri — dà risultati simili all'hamstring; il tendine rotuleo mostra un piccolo squilibrio fra le due gambe nei primi mesi, che si pareggia entro un anno. In generale, anche dopo il pieno recupero della simmetria, l'altezza e la potenza del salto restano un po' ridotte fino a cinque anni: un dato di cui parlare nel percorso di ritorno allo sport, qualunque sia l'innesto."}, "4": {"video": "Uno studio su oltre 400 pazienti seguiti per cinque anni dopo la ricostruzione del legamento crociato anteriore mostra che la presenza e la gravità di un danno alla cartilagine, scoperto durante l'intervento, non cambiano le probabilità di tornare a fare sport né i tempi per farlo. Chi ha un danno cartilagineo importante insieme a un danno al menisco, e chi ha un'età più avanzata, riporta però un recupero soggettivo un po' peggiore: un elemento da discutere prima dell'intervento, non un motivo per rinunciare al rientro allo sport."}, "5": {"video": "Un esperimento di laboratorio su ginocchia animali mostra che, quando si esegue anche un'osteotomia per correggere l'asse della gamba, la sutura di una lesione del menisco vicino al centro dell'articolazione subisce meno stress meccanico durante la flessione profonda del ginocchio. È un esperimento su tessuto animale, non ancora una prova clinica: suggerisce però un motivo pratico per combinare le due procedure quando entrambe sono indicate, e per essere più cauti sulla flessione profonda nella riabilitazione precoce."}, "6": {"video": "Uno studio su oltre 200 pazienti operati di protesi parziale (la parte interna del ginocchio) mostra che chi arriva all'intervento con ansia o sintomi depressivi importanti ha, negli anni successivi, una probabilità più alta che l'altra parte del ginocchio, quella non sostituita, peggiori. Il gruppo con ansia o depressione era piccolo, e i risultati vanno considerati un'ipotesi da confermare: restano comunque un argomento per uno screening psicologico semplice prima dell'intervento."}};
var SOCV={"1": {"video": {"chir": ["Una coorte di 623 pazienti operati di protesi monocompartimentale mediale, confronto fra impianto costruito su misura per il singolo ginocchio e impianto di serie: a due anni gli esiti riferiti dal paziente — PROMIS Global, PROMIS Physical Function, KOOS-PS — sono sovrapponibili fra i due gruppi, senza differenza nella proporzione che raggiunge la differenza minima clinicamente importante.", "Il dato che cambia il quadro è la revisione chirurgica: 8,9% con l'impianto su misura contro 3,8% con quello di serie (p=0,010), trainata soprattutto dalla mobilizzazione asettica, quasi sei volte più frequente nel gruppo custom (4,8% contro 0,8%; p=0,006).", "È uno studio di un solo centro, retrospettivo, non randomizzato, e non specifica il marchio dell'impianto custom: ma con questi numeri, l'onere della prova si sposta su chi propone la personalizzazione come vantaggio, non su chi resta con l'impianto standard."], "misto": ["Uno studio su oltre 600 pazienti operati di protesi parziale di ginocchio confronta un impianto pianificato su misura per il singolo paziente con un impianto di serie, standard.", "A due anni, i risultati percepiti dai pazienti sono simili nei due gruppi, ma l'impianto su misura si è dovuto sostituire più spesso — quasi il doppio delle volte — soprattutto perché si è allentato dall'osso.", "È uno studio di un solo centro, non un confronto randomizzato: un motivo in più per chiedere sempre l'evidenza clinica dietro una tecnologia presentata come più avanzata, prima di considerarla automaticamente migliore."], "pazienti": ["Uno studio su centinaia di pazienti operati di protesi parziale di ginocchio ha confrontato un impianto costruito su misura per il singolo ginocchio con un impianto standard, di serie.", "Dopo due anni, i pazienti operati con i due tipi di impianto si sentivano ugualmente soddisfatti, ma l'impianto su misura si è dovuto sostituire più spesso perché si allentava dall'osso.", "Non è un motivo per preoccuparsi se hai già un impianto standard: questo studio suggerisce anzi che la scelta più diffusa resta una scelta solida, senza bisogno di cercare qualcosa di «più personalizzato»."]}, "linkedin": {"chir": ["Coorte retrospettiva monocentrica, 623 pazienti (124 custom, 499 off-the-shelf), protesi monocompartimentale mediale, follow-up minimo 2 anni: PROM assoluti, delta e MCID comparabili fra i due impianti su tutte le misure (PROMIS Global, PROMIS PF-10a, KOOS-PS; tutti p>0,05).", "Revisione a 2 anni più frequente con l'impianto custom (8,9% contro 3,8%; p=0,010), soprattutto per mobilizzazione asettica (4,8% contro 0,8%; p=0,006). Nessuna differenza sulle altre indicazioni alla revisione o sulle complicanze a 90 giorni.", "Limiti: monocentrico, non randomizzato, marchio dell'impianto custom non specificato. Un segnale di cautela sulla personalizzazione implantare in artroplastica parziale, da verificare con dati multicentrici."], "misto": ["Uno studio su 623 pazienti operati di protesi parziale di ginocchio confronta un impianto su misura con uno di serie: risultati riferiti dal paziente simili, ma più revisioni con l'impianto personalizzato.", "La causa principale è la mobilizzazione asettica, quasi sei volte più frequente con il custom: un dato da conoscere prima di scegliere una tecnologia presentata come più avanzata.", "Studio di un solo centro, non randomizzato: un'indicazione di cautela, non ancora una prova definitiva contro la personalizzazione implantare."], "pazienti": ["Un impianto di ginocchio «su misura» per la protesi parziale non ha dato, in questo studio su centinaia di pazienti, risultati migliori di un impianto standard.", "Anzi, si è dovuto sostituire più spesso nei due anni successivi all'intervento, soprattutto per un allentamento dall'osso.", "Un motivo in più per non dare per scontato che «personalizzato» significhi automaticamente «migliore»."]}, "instagram": {"chir": ["623 pazienti, protesi monocompartimentale: PROM comparabili fra impianto custom e off-the-shelf, ma revisione più frequente con il custom (8,9% vs 3,8%; p=0,010), soprattutto per mobilizzazione asettica.", "Monocentrico, non randomizzato: un segnale di cautela sulla personalizzazione implantare, da confermare con dati multicentrici.", "Fonte: The Journal of Arthroplasty, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["L'impianto «su misura» per la protesi parziale di ginocchio non batte quello standard: stessi risultati per il paziente, più revisioni per allentamento.", "Uno studio di un solo centro: un'indicazione di cautela sulla tecnologia presentata come più avanzata.", "Un dato utile per chi valuta insieme al chirurgo il tipo di impianto più adatto."], "pazienti": ["Un impianto di ginocchio «personalizzato» non ha dato risultati migliori di uno standard in questo studio su centinaia di pazienti — anzi, si è allentato più spesso.", "Se hai già un impianto standard, questo studio è piuttosto rassicurante.", "Parlane comunque con il tuo chirurgo se ti propongono un impianto su misura: chiedi quali dati lo sostengono."]}, "reel": {"chir": ["[623 pazienti, protesi parziale di ginocchio] Impianto su misura o di serie: risultati per il paziente uguali.", "[Revisione a 2 anni: 8,9% vs 3,8%, p=0,010] Ma il custom si allenta di più.", "[Monocentrico, non randomizzato] Un segnale di cautela, non ancora una prova definitiva."], "misto": ["[Protesi parziale di ginocchio] L'impianto «su misura» non batte quello standard.", "[Più revisioni con il custom] Soprattutto per allentamento dall'osso.", "[Uno studio, un centro] Cautela prima di dire «più avanzato»."], "pazienti": ["[Impianto di ginocchio personalizzato] Non dà risultati migliori di uno standard.", "[Anzi, si allenta di più] Lo mostra uno studio su centinaia di pazienti.", "[Hai già un impianto standard?] Questo studio è una buona notizia per te."]}}, "2": {"video": {"chir": ["Il tritato di cartilagine autologa tiene testa a microfrattura e ACI", "Revisione sistematica di 41 studi (2116 pazienti): esiti clinici comparabili fra impianto di cartilagine tritata autologa (AMCI), microfrattura e impianto di condrociti autologhi/matrix-assisted, con fallimento numericamente più basso per l'AMCI (0% contro 1,32% e 3,21%).", "Follow-up medio dell'AMCI meno della metà di quello delle altre due tecniche (29,3 contro 58-61 mesi) e nessun pooling statistico per l'eterogeneità: un segnale favorevole, non ancora una dimostrazione di equivalenza a lungo termine."], "misto": ["Il tritato di cartilagine del paziente regge il confronto con le tecniche di riferimento.", "Una revisione di 41 studi scientifici mette a confronto tre modi di riparare un danno alla cartilagine del ginocchio: il tritato di cartilagine prelevata dallo stesso paziente, la microfrattura e l'impianto di cellule cartilaginee coltivate in laboratorio. I risultati clinici sono simili, e il tritato ha avuto meno fallimenti nel periodo osservato.", "Il tritato di cartilagine è stato seguito per meno tempo delle altre due tecniche: il giudizio a lungo termine resta da confermare."], "pazienti": ["Riparare la cartilagine del ginocchio: una tecnica più semplice tiene il passo.", "Una revisione di molti studi mostra che triturare un pezzetto di cartilagine sana del paziente e reimpiantarlo dà risultati simili a tecniche più complesse e più costose, come coltivare le cellule della cartilagine in laboratorio.", "È un dato incoraggiante, ma il periodo di osservazione per la tecnica più semplice è ancora più corto: prima di dire che funziona altrettanto bene nel tempo serve seguire i pazienti più a lungo."]}, "linkedin": {"chir": ["Revisione sistematica PRISMA, 41 studi/2116 pazienti (224 AMCI, 302 MFX, 1590 ACI/MACI): nessuna differenza significativa su IKDC, KOOS, Lysholm, Tegner, VAS al follow-up più recente.", "Fallimento più basso con AMCI (0%) rispetto a MFX (1,32%) e ACI/MACI (3,21%); follow-up medio AMCI 29,3 mesi, meno della metà di MFX/ACI (58,6-61,1 mesi).", "Nessun pooling statistico per l'eterogeneità, nessuna caratterizzazione della filiera AutoCart: un segnale favorevole al minced cartilage in generale, non ancora una risposta alla tensione sulla variabilità del tessuto di partenza."], "misto": ["Una revisione di 41 studi mette a confronto tre tecniche per riparare un danno alla cartilagine del ginocchio: risultati clinici simili, con meno fallimenti per la tecnica più semplice (il tritato di cartilagine autologa).", "Il periodo di osservazione per questa tecnica è però più corto delle altre due: un buon segnale, non ancora un giudizio definitivo a lungo termine.", "Utile per il colloquio con i pazienti su alternative meno invasive per i danni cartilaginei focali."], "pazienti": ["Una revisione di molti studi mostra che triturare un pezzetto di cartilagine sana del paziente e reimpiantarlo dà risultati simili a tecniche più complesse per riparare il ginocchio.", "È una tecnica più semplice, con un periodo di osservazione finora più corto: promettente, da confermare nel tempo.", "Un'opzione in più da conoscere se il tuo chirurgo ti parla di un danno alla cartilagine del ginocchio."]}, "instagram": {"chir": ["41 studi, 2116 pazienti: minced cartilage (AMCI) esiti comparabili a microfrattura e ACI/MACI, fallimento più basso (0% vs 1,32%/3,21%) ma follow-up più corto (29,3 vs 58-61 mesi).", "Nessun pooling statistico, nessun dato specifico sulla filiera AutoCart: segnale favorevole, non ancora conclusivo a lungo termine.", "Fonte: Arthroscopy, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["Il tritato di cartilagine autologa tiene testa a tecniche più complesse per riparare la cartilagine del ginocchio, mostra una revisione di 41 studi.", "Osservato per meno tempo delle altre tecniche: promettente, da confermare.", "Un'alternativa meno invasiva di cui parlare col proprio chirurgo."], "pazienti": ["Triturare un pezzo di cartilagine sana del paziente e reimpiantarlo funziona quanto tecniche più complesse, mostra una revisione di molti studi.", "Osservato per meno tempo: un buon segnale, non ancora definitivo.", "Chiedi al tuo chirurgo se è un'opzione adatta al tuo caso."]}, "reel": {"chir": ["[41 studi, 2116 pazienti] Minced cartilage: esiti comparabili a microfrattura e ACI.", "[Fallimento 0% vs 1,3%/3,2%] Ma follow-up più corto — 29 mesi contro 58-61.", "[Nessun pooling statistico] Segnale favorevole, non ancora conclusivo."], "misto": ["[Cartilagine del ginocchio] Il tritato autologo tiene testa a tecniche più complesse.", "[41 studi a confronto] Risultati simili, meno fallimenti nel periodo osservato.", "[Osservato per meno tempo] Promettente, da confermare nel tempo."], "pazienti": ["[Danno alla cartilagine] Triturare un pezzo sano e reimpiantarlo funziona quanto tecniche più complesse.", "[Una revisione di 41 studi] Lo conferma, con buoni risultati.", "[Osservato da meno tempo] Chiedine al tuo chirurgo."]}}, "3": {"video": {"chir": ["Il tipo di innesto pesa (poco) sul salto verticale dopo il crociato.", "Revisione sistematica di 47 studi (oltre 3400 pazienti): l'altezza di salto con tendine quadricipitale non differisce da hamstring; il tendine rotuleo mostra maggiore asimmetria eccentrica nella fase precoce rispetto a hamstring, con pareggiamento dopo 9-12 mesi. Deficit di altezza e potenza fino a 5 anni in generale, indipendentemente dall'innesto.", "L'89,4% degli studi non è randomizzato e la certezza dell'evidenza è bassa o molto bassa ovunque: un quadro di direzione, non un dato da usare da solo nel colloquio sul rientro."], "misto": ["Il tipo di innesto per il crociato conta poco sulla capacità di saltare.", "Una revisione di 47 studi scientifici confronta diversi tipi di innesto usati per ricostruire il legamento crociato anteriore, misurando quanto bene i pazienti tornano a saltare. Il tendine quadricipitale — l'innesto più usato oggi in molti centri — dà risultati simili all'hamstring; il tendine rotuleo mostra un piccolo squilibrio fra le due gambe nei primi mesi, che si pareggia entro un anno.", "In generale, anche dopo il pieno recupero della simmetria, l'altezza e la potenza del salto restano un po' ridotte fino a cinque anni: un dato di cui parlare nel percorso di ritorno allo sport, qualunque sia l'innesto."], "pazienti": ["Dopo il crociato, il tipo di innesto non decide da solo quanto salterai bene.", "Una grande revisione di studi mostra che i diversi tipi di innesto usati per ricostruire il legamento crociato del ginocchio danno risultati simili sulla capacità di saltare, anche se i tempi di recupero completo possono variare leggermente nei primi mesi.", "Anche quando il ginocchio sembra tornato normale, l'altezza del salto può restare un po' più bassa per diversi anni: un motivo per continuare la riabilitazione specifica anche dopo il ritorno allo sport."]}, "linkedin": {"chir": ["Revisione sistematica PRISMA/SWiM, 47 studi (>3400 pazienti), protocollo PROSPERO: altezza di salto con tendine quadricipitale comparabile a hamstring; BPTB con maggiore asimmetria eccentrica nella fase precoce/intermedia rispetto a hamstring, pareggiamento a 9-12 mesi.", "Deficit di altezza/potenza di salto fino a 5 anni in generale, indipendentemente dall'innesto; nessuno dei 47 studi lega la performance di salto a un esito duro come il reinfortunio.", "89,4% degli studi non randomizzati, certezza GRADE bassa/molto bassa ovunque: alimenta la tensione sul criterio di rientro, che resta aperta."], "misto": ["Una revisione di 47 studi scientifici mostra che il tipo di innesto per il crociato anteriore conta relativamente poco sulla capacità di saltare dopo l'intervento.", "Anche dopo il recupero della simmetria fra le due gambe, altezza e potenza del salto restano un po' ridotte fino a cinque anni, qualunque sia l'innesto usato.", "Un argomento per non fermare la riabilitazione alla sola misura della simmetria."], "pazienti": ["Una grande revisione di studi mostra che i diversi tipi di innesto per il crociato danno risultati simili sulla capacità di saltare dopo l'intervento.", "Anche quando il ginocchio sembra tornato normale, l'altezza del salto può restare un po' più bassa per diversi anni.", "Un motivo per continuare la riabilitazione specifica anche dopo il ritorno allo sport."]}, "instagram": {"chir": ["47 studi, oltre 3400 pazienti: altezza di salto con tendine quadricipitale comparabile a hamstring; BPTB più asimmetrico nei primi mesi, si pareggia a 9-12 mesi.", "Deficit di altezza/potenza fino a 5 anni indipendentemente dall'innesto; nessun legame con il reinfortunio in nessuno dei 47 studi.", "Fonte: Journal of Clinical Medicine, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["Il tipo di innesto per il crociato conta poco sulla capacità di saltare, mostra una revisione di 47 studi.", "Altezza e potenza del salto restano un po' ridotte fino a 5 anni, con ogni innesto.", "Utile per il colloquio sul rientro allo sport dopo l'intervento."], "pazienti": ["Diversi tipi di innesto per il crociato danno risultati simili sulla capacità di saltare, mostra una grande revisione di studi.", "L'altezza del salto può restare un po' più bassa per anni, anche a ginocchio guarito.", "Continua la riabilitazione specifica anche dopo il ritorno allo sport."]}, "reel": {"chir": ["[47 studi, >3400 pazienti] Tendine quadricipitale: salto comparabile a hamstring.", "[BPTB più asimmetrico nei primi mesi] Si pareggia a 9-12 mesi.", "[Deficit fino a 5 anni] Con ogni innesto, nessun legame col reinfortunio."], "misto": ["[Dopo il crociato] Il tipo di innesto conta poco sul salto.", "[47 studi a confronto] Piccole differenze nei primi mesi, poi si pareggiano.", "[Fino a 5 anni] Altezza e potenza restano un po' ridotte."], "pazienti": ["[Innesto per il crociato] Tipi diversi, risultati simili sul salto.", "[Anche a ginocchio guarito] L'altezza del salto può restare più bassa per anni.", "[Continua la riabilitazione] Anche dopo il rientro allo sport."]}}, "4": {"video": {"chir": ["Il danno cartilagineo non impedisce il rientro allo sport dopo il crociato.", "Coorte di 441 pazienti a 5 anni dalla ricostruzione del LCA: gravità e sede della lesione condrale associata non predicono né il tasso (83% globale) né i tempi di rientro allo sport; età più avanzata e lesione condrale mediale di alto grado con danno meniscale associato predicono invece esiti riferiti dal paziente peggiori.", "Livello IV, monocentrico, innesto non specificato: un dato di counseling più che di indicazione chirurgica."], "misto": ["Un danno alla cartilagine scoperto durante l'intervento al crociato non impedisce di tornare allo sport.", "Uno studio su oltre 400 pazienti seguiti per cinque anni dopo la ricostruzione del legamento crociato anteriore mostra che la presenza e la gravità di un danno alla cartilagine, scoperto durante l'intervento, non cambiano le probabilità di tornare a fare sport né i tempi per farlo.", "Chi ha un danno cartilagineo importante insieme a un danno al menisco, e chi ha un'età più avanzata, riporta però un recupero soggettivo un po' peggiore: un elemento da discutere prima dell'intervento, non un motivo per rinunciare al rientro allo sport."], "pazienti": ["Un danno alla cartilagine trovato durante l'operazione al crociato non ti impedisce di tornare a giocare.", "Uno studio su centinaia di pazienti, seguiti per cinque anni dopo l'intervento al legamento crociato del ginocchio, mostra che scoprire un danno alla cartilagine durante l'operazione non cambia le probabilità di tornare allo sport.", "Chi ha anche un danno al menisco insieme al danno cartilagineo, o un'età più avanzata, può sentirsi un po' meno soddisfatto del recupero: vale la pena parlarne con il chirurgo prima dell'intervento, per sapere cosa aspettarsi."]}, "linkedin": {"chir": ["Coorte retrospettiva, 441 pazienti, follow-up 5 anni: gravità e sede della lesione condrale associata non predicono RTP (83% globale), performance né livello di attività dopo ACLR.", "Lesione condrale mediale di alto grado + danno meniscale associato, ed età più avanzata, predicono esiti riferiti dal paziente peggiori (IKDC più basso, p<0,05).", "Livello IV, monocentrico, innesto non specificato: un dato di counseling, non di indicazione chirurgica."], "misto": ["Uno studio su oltre 400 pazienti seguiti 5 anni dopo la ricostruzione del crociato mostra che un danno alla cartilagine scoperto durante l'intervento non cambia le probabilità di tornare allo sport.", "Chi ha anche un danno al menisco insieme, o un'età più avanzata, riporta un recupero soggettivo un po' peggiore.", "Un elemento da discutere nel counseling pre-operatorio, non un motivo per temere il rientro allo sport."], "pazienti": ["Uno studio su centinaia di pazienti mostra che un danno alla cartilagine trovato durante l'intervento al crociato non impedisce di tornare a fare sport.", "Chi ha anche un danno al menisco, o un'età più avanzata, può sentirsi un po' meno soddisfatto del recupero.", "Vale la pena parlarne col chirurgo prima dell'intervento, per sapere cosa aspettarsi."]}, "instagram": {"chir": ["441 pazienti, 5 anni dopo ACLR: gravità/sede della lesione condrale non predicono RTP (83% globale) né performance.", "Lesione mediale alto grado + danno meniscale + età predicono IKDC peggiore (p<0,05).", "Fonte: Arthroscopy, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["Un danno alla cartilagine scoperto durante l'intervento al crociato non impedisce di tornare allo sport, mostra uno studio su 441 pazienti.", "Danno meniscale associato ed età contano di più sul recupero soggettivo.", "Un dato utile per il colloquio pre-operatorio."], "pazienti": ["Un danno alla cartilagine trovato durante l'operazione al crociato non ti impedisce di tornare a giocare, mostra uno studio su centinaia di pazienti.", "Danno al menisco insieme, o età più avanzata, possono rendere il recupero un po' meno soddisfacente.", "Parlane con il tuo chirurgo prima dell'intervento."]}, "reel": {"chir": ["[441 pazienti, 5 anni] Lesione condrale: non cambia il rientro allo sport.", "[83% RTP globale] Stesso tasso a ogni grado di lesione.", "[Danno meniscale + età] Predicono invece un IKDC peggiore."], "misto": ["[Dopo il crociato] Un danno alla cartilagine non blocca il rientro allo sport.", "[441 pazienti, 5 anni] Stesse probabilità di tornare a giocare.", "[Danno al menisco insieme] Conta di più sul recupero percepito."], "pazienti": ["[Danno alla cartilagine e crociato] Non ti impedisce di tornare a giocare.", "[Uno studio su centinaia di pazienti] Lo conferma a 5 anni.", "[Parlane col chirurgo] Soprattutto se c'è anche un danno al menisco."]}}, "5": {"video": {"chir": ["L'osteotomia scarica la sutura della radice meniscale, mostra un modello di laboratorio.", "Studio biomeccanico su 10 ginocchia porcine: l'osteotomia tibiale alta riduce la forza di trazione al sito di sutura di una lesione radiale posteriore del menisco mediale di 6,16N (mediale) e 6,71N (laterale) a 90° di flessione (p≤0,003), senza differenza a 30-60°.", "Modello animale, tempo zero, nessuna misura clinica: non è la tua tecnica esatta di pull-out transtibiale, ma un primo dato meccanicistico a sostegno di combinare le due procedure quando indicato."], "misto": ["Correggere l'asse della gamba può proteggere la riparazione del menisco.", "Un esperimento di laboratorio su ginocchia animali mostra che, quando si esegue anche un'osteotomia per correggere l'asse della gamba, la sutura di una lesione del menisco vicino al centro dell'articolazione subisce meno stress meccanico durante la flessione profonda del ginocchio.", "È un esperimento su tessuto animale, non ancora una prova clinica: suggerisce però un motivo pratico per combinare le due procedure quando entrambe sono indicate, e per essere più cauti sulla flessione profonda nella riabilitazione precoce."], "pazienti": ["Perché a volte si corregge l'asse della gamba insieme alla riparazione del menisco.", "Uno studio di laboratorio su tessuto animale mostra che correggere l'asse della gamba (un'osteotomia) può ridurre lo sforzo meccanico sul punto in cui è stato riparato un menisco danneggiato vicino al centro del ginocchio.", "È ancora un esperimento di laboratorio, non uno studio su pazienti: ma aiuta a capire perché il chirurgo a volte propone le due procedure insieme, quando la gamba storta lo giustifica."]}, "linkedin": {"chir": ["Studio biomeccanico, 10 ginocchia porcine: l'HTO riduce la forza di trazione al sito di sutura di una lesione radiale posteriore del menisco mediale di 6,16N (mediale) e 6,71N (laterale) a 90° di flessione (p≤0,003); nessuna differenza a 30-60°.", "Non è la tecnica esatta di pull-out transtibiale della radice, ma un primo dato meccanicistico su perché combinare le due procedure protegga la riparazione.", "Modello animale, tempo zero: rafforza la soglia di varo ≥5° già raccomandata, non la sostituisce."], "misto": ["Un esperimento di laboratorio mostra che correggere l'asse della gamba con un'osteotomia può ridurre lo sforzo meccanico sulla riparazione di un menisco lesionato vicino al centro del ginocchio.", "Un motivo pratico per combinare le due procedure quando entrambe sono indicate.", "Studio su tessuto animale, non ancora una prova clinica diretta."], "pazienti": ["Uno studio di laboratorio mostra che correggere l'asse della gamba può proteggere meccanicamente la riparazione di un menisco danneggiato.", "Aiuta a capire perché a volte il chirurgo propone le due procedure insieme.", "È ancora un esperimento su tessuto animale, non uno studio su pazienti."]}, "instagram": {"chir": ["10 ginocchia porcine: l'HTO riduce la forza di trazione sulla sutura della radice meniscale a 90° di flessione (-6,16N mediale, -6,71N laterale; p≤0,003).", "Modello animale, non la tecnica pull-out esatta: primo dato meccanicistico a sostegno della combinazione HTO+riparazione.", "Fonte: Journal of ISAKOS, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["Correggere l'asse della gamba può proteggere la riparazione di un menisco lesionato, mostra un esperimento di laboratorio.", "Un motivo per combinare le due procedure quando indicate.", "Ancora un dato di laboratorio, non clinico."], "pazienti": ["Uno studio di laboratorio mostra che correggere la gamba storta può proteggere la riparazione del menisco.", "Aiuta a capire perché il chirurgo a volte propone le due operazioni insieme.", "È un esperimento su tessuto animale, non ancora su pazienti."]}, "reel": {"chir": ["[10 ginocchia porcine] HTO riduce la forza sulla sutura della radice meniscale.", "[-6,16N a 90° di flessione, p=0,003] Nessun effetto a 30-60°.", "[Modello animale, tempo zero] Primo dato meccanicistico, non la tua tecnica esatta."], "misto": ["[Osteotomia e menisco] Correggere l'asse protegge la riparazione.", "[Esperimento di laboratorio] Meno sforzo meccanico sulla sutura.", "[Non ancora clinico] Ma un motivo pratico per combinarle."], "pazienti": ["[Gamba storta e menisco lesionato] Correggerla può proteggere la riparazione.", "[Uno studio di laboratorio] Lo suggerisce su tessuto animale.", "[Non ancora su pazienti] Ma spiega perché si fanno insieme."]}}, "6": {"video": {"chir": ["Ansia e depressione preoperatorie pesano sulla protesi monocompartimentale.", "Coorte retrospettiva di 203 ginocchia, follow-up medio 70 mesi: progressione artrosica del compartimento laterale nel 26,3% complessivo, ma nel 60,0% dei pazienti con ansia/depressione preoperatoria (HADS≥8) contro il 20,2% senza; associazione confermata all'analisi multivariabile.", "Gruppo a rischio piccolo (26/203 ginocchia) e follow-up radiografico disponibile solo nella metà dei casi: risultati esplorativi, dichiarati tali dagli stessi autori."], "misto": ["Lo stato d'animo prima dell'intervento conta anche nella protesi parziale di ginocchio.", "Uno studio su oltre 200 pazienti operati di protesi monocompartimentale (la parte interna del ginocchio) mostra che chi arriva all'intervento con ansia o sintomi depressivi importanti ha, negli anni successivi, una probabilità più alta che l'altra parte del ginocchio, quella non sostituita, peggiori.", "Il gruppo con ansia o depressione era piccolo, e i risultati vanno considerati un'ipotesi da confermare: restano comunque un argomento per uno screening psicologico semplice prima dell'intervento, non solo per il paziente col ginocchio."], "pazienti": ["Come ti senti prima dell'intervento può contare anche dopo, per la protesi parziale.", "Uno studio su pazienti operati di protesi parziale di ginocchio mostra che chi arriva all'intervento con ansia o tristezza importanti tende, negli anni dopo, ad avere risultati un po' meno soddisfacenti e un rischio più alto che l'altra parte del ginocchio si usuri.", "Se prima dell'intervento ti senti particolarmente ansioso o giù di morale, parlane con il tuo medico: prendersene cura può fare parte della preparazione all'operazione, non solo la parte fisica."]}, "linkedin": {"chir": ["Coorte retrospettiva, 203 ginocchia, follow-up medio 70 mesi: progressione artrosica del compartimento laterale nel 60,0% dei pazienti con ansia/depressione preoperatoria (HADS≥8) contro il 20,2% senza; associazione confermata in multivariabile.", "OKS, FJS e Kujala peggiori nel gruppo con ansia/depressione al follow-up finale.", "Gruppo a rischio piccolo (26/203), follow-up radiografico solo nella metà dei casi: risultati esplorativi, dichiarati tali dagli autori."], "misto": ["Uno studio su oltre 200 pazienti operati di protesi parziale di ginocchio mostra che chi arriva all'intervento con ansia o depressione importanti ha, negli anni dopo, un rischio più alto che l'altra parte del ginocchio peggiori.", "Un argomento per uno screening psicologico semplice prima dell'intervento.", "Studio con un gruppo a rischio piccolo: un'ipotesi da confermare, non ancora una regola."], "pazienti": ["Uno studio mostra che chi arriva all'intervento di protesi parziale con ansia o tristezza importanti tende ad avere, negli anni dopo, risultati un po' meno soddisfacenti.", "Se ti senti così prima dell'intervento, parlane con il tuo medico.", "Prendersi cura anche di questo aspetto può far parte della preparazione all'operazione."]}, "instagram": {"chir": ["203 ginocchia, follow-up 70 mesi: progressione artrosica laterale nel 60,0% con ansia/depressione preoperatoria (HADS≥8) contro 20,2% senza.", "Gruppo a rischio piccolo (26/203): risultati esplorativi, dichiarati dagli autori.", "Fonte: Journal of Clinical Medicine, settembre 2026 — link a PubMed nella scheda dell'app."], "misto": ["Ansia e depressione prima dell'intervento pesano sulla protesi parziale di ginocchio, mostra uno studio su oltre 200 pazienti.", "Un argomento per uno screening psicologico preoperatorio semplice.", "Gruppo a rischio piccolo: da confermare."], "pazienti": ["Chi arriva all'intervento di protesi parziale con ansia o tristezza importanti può avere risultati un po' meno soddisfacenti negli anni dopo.", "Parlane con il tuo medico se ti senti così prima dell'intervento.", "Fa parte della preparazione all'operazione, non solo la parte fisica."]}, "reel": {"chir": ["[203 ginocchia, 70 mesi] Ansia/depressione preoperatoria e progressione artrosica laterale.", "[60,0% vs 20,2%] Associazione confermata in multivariabile.", "[Gruppo piccolo, 26/203] Risultato esplorativo, non definitivo."], "misto": ["[Protesi parziale di ginocchio] Lo stato d'animo prima conta anche dopo.", "[Ansia o depressione] Rischio più alto che l'altra parte peggiori.", "[Studio esplorativo] Un argomento per uno screening preoperatorio."], "pazienti": ["[Prima dell'intervento] Ansia o tristezza possono contare sul recupero.", "[Uno studio lo suggerisce] Su oltre 200 pazienti operati.", "[Parlane col tuo medico] Fa parte della preparazione."]}}};
var TAGS={"1": {"linkedin": "#ProtesiGinocchio #Monocompartimentale #Ortopedia", "instagram": "#protesiginocchio #monocompartimentale #ortopedia #chirurgiaortopedica #revisioneprotesi #ricercamedica #artroplastica #kneesurgery #evidenzaclinica", "kw": "protesi monocompartimentale su misura, revisione protesi ginocchio"}, "2": {"linkedin": "#Cartilagine #ChirurgiaGinocchio #MincedCartilage", "instagram": "#cartilagine #ginocchio #chirurgiaortopedica #mincedcartilage #autocart #ricercamedica #ortopedia #medicinasportiva #artroscopia", "kw": "riparazione cartilagine ginocchio, minced cartilage tecnica"}, "3": {"linkedin": "#LCA #RitornoSport #ChirurgiaOrtopedica", "instagram": "#legamentocrociato #lca #ritornosport #riabilitazione #innesto #ortopedia #medicinasportiva #ricercascientifica #kneesurgery", "kw": "innesto crociato anteriore, salto dopo LCA"}, "4": {"linkedin": "#LCA #Cartilagine #RitornoSport", "instagram": "#legamentocrociato #lca #cartilagine #ritornosport #ortopedia #chirurgiaginocchio #ricercamedica #medicinasportiva #kneesurgery", "kw": "cartilagine crociato anteriore, rientro sport LCA"}, "5": {"linkedin": "#Menisco #Osteotomia #ChirurgiaGinocchio", "instagram": "#menisco #osteotomia #ginocchio #chirurgiaortopedica #biomeccanica #ricercascientifica #suturamenisco #ortopedia #artroscopia", "kw": "osteotomia menisco, riparazione radice menisco"}, "6": {"linkedin": "#ProtesiGinocchio #Ortopedia #SaluteMentale", "instagram": "#protesiginocchio #monocompartimentale #ortopedia #ansiaedepressione #saluteemozionale #ricercamedica #chirurgiaortopedica #kneesurgery #artroplastica", "kw": "protesi monocompartimentale, ansia depressione intervento"}};
var NLB={"1": {"prof": ["La protesi monocompartimentale su misura rivela più revisioni, non meno", "Coorte di 623 pazienti, follow-up 2 anni: nessun vantaggio sugli esiti riferiti dal paziente per l'impianto custom rispetto a quello di serie, ma tasso di revisione più alto (8,9% contro 3,8%; p=0,010), soprattutto per mobilizzazione asettica (4,8% contro 0,8%; p=0,006).", "Studio retrospettivo monocentrico, non randomizzato, marchio dell'impianto custom non specificato: un segnale di cautela, non ancora una controindicazione definitiva alla personalizzazione."], "mix": ["L'impianto di ginocchio «su misura» non batte quello standard, anzi", "Uno studio su oltre 600 pazienti operati di protesi parziale di ginocchio confronta un impianto pianificato su misura per il singolo paziente con un impianto di serie standard. A due anni, i risultati percepiti dai pazienti sono simili, ma l'impianto su misura si è dovuto sostituire più spesso, soprattutto perché si è allentato.", "È uno studio di un solo centro, non un confronto randomizzato: un motivo per chiedere sempre l'evidenza clinica dietro a una tecnologia presentata come più avanzata, prima di considerarla automaticamente migliore."], "paz": ["L'impianto «personalizzato» per la protesi di ginocchio non garantisce risultati migliori", "Uno studio su centinaia di pazienti operati di protesi parziale di ginocchio mostra che l'impianto costruito su misura per il singolo ginocchio non ha dato risultati percepiti migliori rispetto a un impianto standard, e si è dovuto sostituire più spesso nei due anni successivi.", "Non è un motivo per preoccuparsi se hai già un impianto standard: anzi, questo studio suggerisce che la scelta più diffusa resta una scelta solida."], "kw": "protesi monocompartimentale su misura, revisione protesi ginocchio"}, "2": {"prof": ["Il tritato di cartilagine autologa tiene testa a microfrattura e ACI", "Revisione sistematica di 41 studi (2116 pazienti): esiti clinici comparabili fra impianto di cartilagine tritata autologa (AMCI), microfrattura e impianto di condrociti autologhi/matrix-assisted, con fallimento numericamente più basso per l'AMCI (0% contro 1,32% e 3,21%).", "Follow-up medio dell'AMCI meno della metà di quello delle altre due tecniche (29,3 contro 58-61 mesi) e nessun pooling statistico per l'eterogeneità: un segnale favorevole, non ancora una dimostrazione di equivalenza a lungo termine."], "mix": ["Il tritato di cartilagine del paziente regge il confronto con le tecniche di riferimento", "Una revisione di 41 studi scientifici mette a confronto tre modi di riparare un danno alla cartilagine del ginocchio: il tritato di cartilagine prelevata dallo stesso paziente, la microfrattura e l'impianto di cellule cartilaginee coltivate in laboratorio. I risultati clinici sono simili, e il tritato ha avuto meno fallimenti nel periodo osservato.", "Il tritato di cartilagine è stato seguito per meno tempo delle altre due tecniche: il giudizio a lungo termine resta da confermare."], "paz": ["Riparare la cartilagine del ginocchio: una tecnica più semplice tiene il passo", "Una revisione di molti studi mostra che triturare un pezzetto di cartilagine sana del paziente e reimpiantarlo dà risultati simili a tecniche più complesse e più costose, come coltivare le cellule della cartilagine in laboratorio.", "È un dato incoraggiante, ma il periodo di osservazione per la tecnica più semplice è ancora più corto: prima di dire che funziona altrettanto bene nel tempo serve seguire i pazienti più a lungo."], "kw": "riparazione cartilagine ginocchio, minced cartilage tecnica"}, "3": {"prof": ["Il tipo di innesto pesa (poco) sul salto verticale dopo il crociato", "Revisione sistematica di 47 studi (oltre 3400 pazienti): l'altezza di salto con tendine quadricipitale non differisce da hamstring; il tendine rotuleo mostra maggiore asimmetria eccentrica nella fase precoce rispetto a hamstring, con pareggiamento dopo 9-12 mesi. Deficit di altezza e potenza fino a 5 anni in generale, indipendentemente dall'innesto.", "L'89,4% degli studi non è randomizzato e la certezza dell'evidenza è bassa o molto bassa ovunque: un quadro di direzione, non un dato da usare da solo nel colloquio sul rientro."], "mix": ["Il tipo di innesto per il crociato conta poco sulla capacità di saltare", "Una revisione di 47 studi scientifici confronta diversi tipi di innesto usati per ricostruire il legamento crociato anteriore, misurando quanto bene i pazienti tornano a saltare. Il tendine quadricipitale — l'innesto più usato oggi in molti centri — dà risultati simili all'hamstring; il tendine rotuleo mostra un piccolo squilibrio fra le due gambe nei primi mesi, che si pareggia entro un anno.", "In generale, anche dopo il pieno recupero della simmetria, l'altezza e la potenza del salto restano un po' ridotte fino a cinque anni: un dato di cui parlare nel percorso di ritorno allo sport, qualunque sia l'innesto."], "paz": ["Dopo il crociato, il tipo di innesto non decide da solo quanto salterai bene", "Una grande revisione di studi mostra che i diversi tipi di innesto usati per ricostruire il legamento crociato del ginocchio danno risultati simili sulla capacità di saltare, anche se i tempi di recupero completo possono variare leggermente nei primi mesi.", "Anche quando il ginocchio sembra tornato normale, l'altezza del salto può restare un po' più bassa per diversi anni: un motivo per continuare la riabilitazione specifica anche dopo il ritorno allo sport."], "kw": "innesto crociato anteriore, salto dopo ricostruzione LCA"}, "4": {"prof": ["Il danno cartilagineo non impedisce il rientro allo sport dopo il crociato", "Coorte di 441 pazienti a 5 anni dalla ricostruzione del LCA: gravità e sede della lesione condrale associata non predicono né il tasso (83% globale) né i tempi di rientro allo sport; età più avanzata e lesione condrale mediale di alto grado con danno meniscale associato predicono invece esiti riferiti dal paziente peggiori.", "Livello IV, monocentrico, innesto non specificato: un dato di counseling più che di indicazione chirurgica."], "mix": ["Un danno alla cartilagine scoperto durante l'intervento al crociato non impedisce di tornare allo sport", "Uno studio su oltre 400 pazienti seguiti per cinque anni dopo la ricostruzione del legamento crociato anteriore mostra che la presenza e la gravità di un danno alla cartilagine, scoperto durante l'intervento, non cambiano le probabilità di tornare a fare sport né i tempi per farlo.", "Chi ha un danno cartilagineo importante insieme a un danno al menisco, e chi ha un'età più avanzata, riporta però un recupero soggettivo un po' peggiore: un elemento da discutere prima dell'intervento, non un motivo per rinunciare al rientro allo sport."], "paz": ["Un danno alla cartilagine trovato durante l'operazione al crociato non ti impedisce di tornare a giocare", "Uno studio su centinaia di pazienti, seguiti per cinque anni dopo l'intervento al legamento crociato del ginocchio, mostra che scoprire un danno alla cartilagine durante l'operazione non cambia le probabilità di tornare allo sport.", "Chi ha anche un danno al menisco insieme al danno cartilagineo, o un'età più avanzata, può sentirsi un po' meno soddisfatto del recupero: vale la pena parlarne con il chirurgo prima dell'intervento, per sapere cosa aspettarsi."], "kw": "cartilagine crociato anteriore, rientro sport dopo LCA"}, "5": {"prof": ["L'osteotomia scarica la sutura della radice meniscale, mostra un modello di laboratorio", "Studio biomeccanico su 10 ginocchia porcine: l'osteotomia tibiale alta riduce la forza di trazione al sito di sutura di una lesione radiale posteriore del menisco mediale di 6,16N (mediale) e 6,71N (laterale) a 90° di flessione (p≤0,003), senza differenza a 30-60°.", "Modello animale, tempo zero, nessuna misura clinica: non è la tua tecnica esatta di pull-out transtibiale, ma un primo dato meccanicistico a sostegno di combinare le due procedure quando indicato."], "mix": ["Correggere l'asse della gamba può proteggere la riparazione del menisco", "Un esperimento di laboratorio su ginocchia animali mostra che, quando si esegue anche un'osteotomia per correggere l'asse della gamba, la sutura di una lesione del menisco vicino al centro dell'articolazione subisce meno stress meccanico durante la flessione profonda del ginocchio.", "È un esperimento su tessuto animale, non ancora una prova clinica: suggerisce però un motivo pratico per combinare le due procedure quando entrambe sono indicate, e per essere più cauti sulla flessione profonda nella riabilitazione precoce."], "paz": ["Perché a volte si corregge l'asse della gamba insieme alla riparazione del menisco", "Uno studio di laboratorio su tessuto animale mostra che correggere l'asse della gamba (un'osteotomia) può ridurre lo sforzo meccanico sul punto in cui è stato riparato un menisco danneggiato vicino al centro del ginocchio.", "È ancora un esperimento di laboratorio, non uno studio su pazienti: ma aiuta a capire perché il chirurgo a volte propone le due procedure insieme, quando la gamba storta lo giustifica."], "kw": "osteotomia menisco, riparazione radice menisco"}, "6": {"prof": ["Ansia e depressione preoperatorie pesano sulla protesi monocompartimentale", "Coorte retrospettiva di 203 ginocchia, follow-up medio 70 mesi: progressione artrosica del compartimento laterale nel 26,3% complessivo, ma nel 60,0% dei pazienti con ansia/depressione preoperatoria (HADS≥8) contro il 20,2% senza; associazione confermata all'analisi multivariabile.", "Gruppo a rischio piccolo (26/203 ginocchia) e follow-up radiografico disponibile solo nella metà dei casi: risultati esplorativi, dichiarati tali dagli stessi autori."], "mix": ["Lo stato d'animo prima dell'intervento conta anche nella protesi parziale di ginocchio", "Uno studio su oltre 200 pazienti operati di protesi monocompartimentale (la parte interna del ginocchio) mostra che chi arriva all'intervento con ansia o sintomi depressivi importanti ha, negli anni successivi, una probabilità più alta che l'altra parte del ginocchio, quella non sostituita, peggiori.", "Il gruppo con ansia o depressione era piccolo, e i risultati vanno considerati un'ipotesi da confermare: restano comunque un argomento per uno screening psicologico semplice prima dell'intervento, non solo per il paziente col ginocchio."], "paz": ["Come ti senti prima dell'intervento può contare anche dopo, per la protesi parziale", "Uno studio su pazienti operati di protesi parziale di ginocchio mostra che chi arriva all'intervento con ansia o tristezza importanti tende, negli anni dopo, ad avere risultati un po' meno soddisfacenti e un rischio più alto che l'altra parte del ginocchio si usuri.", "Se prima dell'intervento ti senti particolarmente ansioso o giù di morale, parlane con il tuo medico: prendersene cura può fare parte della preparazione all'operazione, non solo la parte fisica."], "kw": "protesi monocompartimentale, ansia depressione intervento"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"The Journal of Arthroplasty",h:"L'impianto monocompartimentale su misura rivela più revisioni, non meno",v:"Coorte di 623 pazienti: risultati riferiti dal paziente comparabili fra impianto su misura e di serie, ma revisione più frequente con il custom (8,9% contro 3,8%), soprattutto per mobilizzazione asettica.",ax:"Mannina, Ilyas, Kwon",date:"set 2026",meta:"coorte retrospettiva comparativa, 623 pazienti · [III]",pmid:'42735864',doi:'10.1016/j.arth.2026.09.008',journal:"The Journal of Arthroplasty",authors:"Mannina C, Ilyas MH, Kang H, Freeman I, Sampson WT, Kwon YM",design:"Coorte retrospettiva monocentrica (Massachusetts General Hospital), pazienti sottoposti a protesi monocompartimentale mediale con impianto su misura (custom, pianificato su imaging del singolo paziente) o con impianto di serie (off-the-shelf, OTS); confronto di esiti riferiti dal paziente (PROMIS Global Physical/Mental, PROMIS Physical Function SF-10a, KOOS-PS) e di complicanze a 90 giorni e revisioni a 2 anni; follow-up minimo 2 anni con questionari pre e postoperatori completi.",pop:"623 pazienti: 124 con impianto custom, 499 con impianto di serie (OTS); nessuna differenza nelle caratteristiche demografiche o nelle comorbidità basali fra i due gruppi.",results:"Punteggi PROM assoluti, punteggi delta e proporzione di pazienti che raggiungono la differenza minima clinicamente importante (MCID) comparabili fra i due gruppi su tutte le misure (tutti p>0,05). A 2 anni, tasso di revisione più alto con l'impianto custom (8,9% contro 3,8%; p=0,010); revisione per mobilizzazione asettica più frequente con custom (4,8% contro 0,8%; p=0,006). Altre indicazioni alla revisione e le altre complicanze valutate comparabili fra i gruppi (tutti p>0,05).",concl:"Gli autori concludono che l'impianto monocompartimentale su misura non offre un vantaggio sugli esiti riferiti dal paziente rispetto all'impianto di serie, e si associa invece a un tasso di revisione più alto a 2 anni, in particolare per mobilizzazione asettica: i presunti vantaggi teorici della personalizzazione non si traducono, in questa coorte, in esiti clinicamente migliori.",limits:"Retrospettivo, monocentrico, non randomizzato: possibile selezione dei pazienti verso l'uno o l'altro impianto per motivi non misurati · marchio dell'impianto custom non specificato nell'abstract · follow-up di soli 2 anni, la mobilizzazione asettica può manifestarsi anche più tardi in entrambi i gruppi.",perte:"Un argomento di cautela diretto per la tua pratica di protesi monocompartimentale: la personalizzazione dell'impianto, presentata spesso come vantaggio tecnologico, qui si associa a più revisioni per mobilizzazione asettica senza alcun beneficio misurabile sugli esiti riferiti dal paziente. Prima di adottare o raccomandare un impianto su misura, questo dato chiede la stessa domanda che fai per ogni innovazione: il vantaggio teorico si traduce in un esito clinico migliore, o resta sulla carta?"},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Il tritato di cartilagine autologa tiene testa a microfrattura e ACI",v:"Revisione sistematica di 41 studi (2116 pazienti): AMIC/minced cartilage esiti comparabili a microfrattura e ACI, fallimento più basso — ma segue solo 29 mesi di follow-up medio, contro 58-61 delle altre due tecniche.",ax:"Caplan, Sardesai, Cole",date:"set 2026",meta:"revisione sistematica, 41 studi/2116 pazienti · [IV]",pmid:'42743060',doi:'10.1002/arj.70511',journal:"Arthroscopy",authors:"Caplan BE, Sardesai KS, Jesse JE, Synchef D, Mufti YN, Sachs J, Alfonsi S, Kunze KN, Cole BJ",design:"Revisione sistematica secondo le linee guida PRISMA (PubMed, Embase, Cochrane, ricerca a maggio 2025); confronto fra impianto di cartilagine tritata autologa (AMCI), microfrattura (MFX) e impianto di condrociti autologhi/matrix-assisted (ACI/MACI) per difetti condrali focali del ginocchio; studi di livello I-IV, 2015-2025, follow-up minimo 12 mesi, almeno due esiti clinici validati; analisi qualitativa con forest plot, sintesi descrittiva senza pooling per l'eterogeneità.",pop:"41 studi, 2116 pazienti: 1590 ACI/MACI, 302 MFX, 224 AMCI. Età media 34,4 anni (ACI/MACI), 45,0 (MFX), 32,7 (AMCI). Follow-up medio 61,1 mesi (ACI/MACI), 58,6 (MFX), 29,3 (AMCI).",results:"Nessuna differenza significativa fra le tre tecniche su IKDC, KOOS, Lysholm, Tegner e VAS dolore al follow-up più recente; IKDC per ACI 50,91-92,70, MACI 34,18-89,57, MFX 37,63-79,53, AMCI 56,97-87,29 (range, non pooled). Fallimento più basso con AMCI (0%) rispetto a MFX (1,32%) e ACI/MACI (3,21%); reoperazioni numericamente più basse con AMCI e MFX (n=10 e n=14) che con ACI/MACI (n=155), riportate in modo eterogeneo fra gli studi.",concl:"Gli autori concludono che l'AMCI mostra esiti clinici almeno comparabili ad ACI, MACI e MFX e può essere un'alternativa appropriata per i difetti condrali focali del ginocchio, ma segnalano che gli studi disponibili sono eterogenei e i dati a lungo termine sull'AMCI restano limitati.",limits:"Follow-up medio dell'AMCI meno della metà di quello di ACI/MACI e MFX (29,3 contro 58-61 mesi): la sopravvivenza a lungo termine non è ancora confrontabile · nessun pooling statistico per l'eterogeneità, solo range descrittivi e forest plot qualitativi · nessuno studio caratterizza la filiera AutoCart specificamente, né la vitalità cellulare del tessuto triturato — la domanda aperta dalla tensione T4 resta aperta.",perte:"È la prima revisione sistematica che mette il minced cartilage a confronto diretto, su esiti clinici, con le due tecniche di riferimento (microfrattura e ACI): il segnale è favorevole, ma il follow-up più corto rende ancora prematuro un giudizio di equivalenza a lungo termine. Non risponde alla domanda specifica della tensione T4 — la variabilità del tessuto di partenza nella filiera AutoCart — che resta un buco di letteratura."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Clinical Medicine",h:"Il tipo di innesto pesa (poco) sul salto verticale dopo il crociato",v:"Revisione di 47 studi (oltre 3400 pazienti): l'altezza di salto con tendine quadricipitale è comparabile a hamstring; deficit di altezza e potenza restano fino a 5 anni, con ogni innesto.",ax:"Kasicki, Błażejewski, Rydzik",date:"set 2026",meta:"revisione sistematica PRISMA/SWiM, 47 studi/>3400 pazienti · [IV]",pmid:'42739595',doi:'10.3390/jcm15176588',journal:"Journal of Clinical Medicine",authors:"Kasicki K, Błażejewski G, Rydzik Ł, Wróbel P, Nowak M, Ambroży T",design:"Revisione sistematica secondo PRISMA 2020 e le linee guida SWiM (Synthesis Without Meta-analysis), protocollo PROSPERO CRD420261386307; ricerca su Scopus, Web of Science, PubMed, MEDLINE, SPORTDiscus fino al 31 gennaio 2026; studi con tipo di innesto definito e test di salto verticale oggettivi (CMJ, SL CMJ/SL VJ, DVJ/DJ, SJ) dopo ricostruzione del LCA nell'adulto; rischio di bias con RoB 2/ROBINS-I/JBI/MINORS, certezza GRADE; sintesi narrativa strutturata, nessun pooling per eterogeneità clinica e metodologica sostanziale.",pop:"47 studi, oltre 3400 partecipanti; 42/47 studi (89,4%) non randomizzati.",results:"BPTB associato a maggiore asimmetria della fase eccentrica nel CMJ bilaterale nella fase precoce/intermedia rispetto a hamstring (HT), con pareggiamento dopo 9-12 mesi (segnale incoerente fra studi, 2 studi non trovano differenza). Tendine quadricipitale (QT): altezza di salto comparabile a HT; un singolo studio di 26 pazienti riporta un profilo di valgo dinamico più favorevole con QT. Autoinnesto e allograft non differiscono nella performance di salto. Decorso bifasico dei deficit in generale: normalizzazione della simmetria dopo circa 2 anni, ma altezza/potenza ridotte fino a 5 anni.",concl:"Gli autori concludono che il tipo di innesto influenza in parte il recupero della performance di salto verticale, in particolare nella fase precoce/intermedia per il confronto BPTB/HT, mentre QT e HT non differiscono per altezza di salto; la certezza dell'evidenza è bassa per una domanda clinica e molto bassa per tutte le altre.",limits:"89,4% degli studi non randomizzati, eterogeneità clinica e metodologica sostanziale — nessun pooling quantitativo eseguito · il dato favorevole al QT sul valgo dinamico deriva da un singolo studio di 26 pazienti · nessuno studio isola l'effetto di un'augmentazione extra-articolare laterale associata all'innesto.",perte:"Tocca direttamente il tuo innesto (tendine quadricipitale): l'altezza di salto non differisce da hamstring, e un singolo studio segnala un profilo di valgo dinamico più favorevole — un segnale nella tua direzione, ma basato su 26 pazienti e senza LET associato. Alimenta la tensione T3: nessuno di questi 47 studi lega la performance di salto a un esito duro come il reinfortunio, e la certezza dell'evidenza resta bassa o molto bassa ovunque."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Il danno cartilagineo non impedisce il rientro allo sport dopo il crociato",v:"Coorte di 441 pazienti a 5 anni: gravità e sede della lesione condrale non predicono il rientro allo sport, ma la sua combinazione con danno meniscale e l'età sì, sugli esiti riferiti dal paziente.",ax:"McAleese, Devitt",date:"set 2026",meta:"coorte retrospettiva, 441 pazienti, follow-up 5 anni · [IV]",pmid:'42743053',doi:'10.1002/arj.70567',journal:"Arthroscopy",authors:"McAleese T, Okoli M, Moran KA, Jackson M, Withers D, Moran R, Devitt BM",design:"Coorte retrospettiva monocentrica (UPMC Sports Surgery Clinic, Dublino), pazienti con ricostruzione primaria del LCA e lesione condrale confermata artroscopicamente, età 13-45 anni, esclusi interventi associati su altri legamenti; grading ICRS della lesione, gestione in situ/condroplastica/microfrattura; follow-up minimo 5 anni; regressione di Cox multivariabile e regressione ordinale per i predittori indipendenti di rientro allo sport (RTP) ed esiti riferiti dal paziente.",pop:"441 pazienti, follow-up medio 61 mesi (range 60-72); età media alla chirurgia 26,8±7,6 anni; 78% maschi.",results:"RTP globale 83% (348/419) a 5 anni, senza differenza significativa fra lesioni di grado 1-2 e 3-4 né nel compartimento mediale (85% contro 77,4%; p=0,179) né in quello laterale (85,1% contro 86,6%; p=0,850); tempo medio alla RTP 13,9±8 mesi, non diverso per gravità della lesione. Reinfortunio controlaterale meno frequente con lesioni di grado 3-4 (4,2%) che 1-2 (12,9%; p=0,033). IKDC più basso con lesioni di grado 3-4 sia nel compartimento mediale (81,0±14,4 contro 85,0±12,9; p=0,020) sia laterale (80,9±15,8 contro 86,9±11,7; p=0,049). Età più avanzata associata a IKDC peggiore (OR 0,94; IC 95% 0,91-0,97; p<0,001) e WOMAC peggiore (OR 1,1; IC 95% 1,01-1,09; p=0,003).",concl:"Gli autori concludono che gravità e sede della lesione condrale non determinano il tasso di RTP, la performance né il livello di attività postoperatorio, mentre la combinazione di lesione condrale mediale di alto grado con coinvolgimento meniscale associato e l'età più avanzata predicono esiti riferiti dal paziente peggiori; ne deducono che il rientro allo sport è raggiungibile nonostante il danno condrale focale.",limits:"Livello IV, monocentrico, retrospettivo · innesto non specificato nell'abstract · il reinfortunio controlaterale più basso nelle lesioni gravi è controintuitivo e non spiegato dagli autori, possibile effetto di selezione o di cautela post-operatoria non misurata.",perte:"Alimenta la tensione T3 da un angolo diverso dalla sola forza: qui il fattore che pesa sugli esiti riferiti dal paziente non è la gravità condrale isolata ma la sua combinazione con danno meniscale e l'età — un argomento per personalizzare il counseling pre-operatorio su chi ha una lesione condrale associata, più che per temere di per sé il grado ICRS nel colloquio sul rientro allo sport."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"L'osteotomia scarica la sutura della radice meniscale a 90°",v:"Modello porcino: l'osteotomia tibiale alta riduce la forza di trazione sulla sutura di una lesione radiale della radice meniscale a 90° di flessione — un primo dato meccanicistico, non ancora clinico.",ax:"Hamaoka, Kamiya, Horita",date:"set 2026",meta:"studio biomeccanico controllato, modello porcino, 10 ginocchia · [V]",pmid:'42744120',doi:'10.1016/j.jisako.2026.101216',journal:"Journal of ISAKOS",authors:"Hamaoka K, Kamiya T, Shiwaku K, Horita K, Ikeda Y, Okada Y, Emori M, Teramoto A",design:"Studio biomeccanico controllato su 10 ginocchia porcine fresche-congelate, sistema robotico a 6 gradi di libertà con cella di carico; lesione radiale completa creata nel segmento posteriore del menisco mediale, riparata con sutura orizzontale a punto singolo; misura della forza di trazione al sito di riparazione (direzione mediale e laterale) sotto carico assiale di 300N a 30°, 60° e 90° di flessione, prima e dopo osteotomia tibiale alta (HTO) sullo stesso ginocchio.",pop:"10 ginocchia porcine fresche-congelate, ciascuna testata in entrambe le condizioni (riparazione sola vs riparazione + HTO).",results:"A 90° di flessione, forza di trazione 16,2±1,9N (sola riparazione) contro 10,0±3,7N (riparazione+HTO) in direzione mediale, e 15,7±2,9N contro 9,0±3,7N in direzione laterale; interazione significativa fra condizione chirurgica e angolo di flessione (mediale p=0,005; laterale p=0,002). Riduzione della forza a 90° di 6,16N (IC 95% 2,64-9,68; p=0,003) in direzione mediale e 6,71N (IC 95% 3,84-9,59; p<0,001) in direzione laterale. Nessuna differenza significativa a 30° o 60° (tutti p≥0,156).",concl:"Gli autori concludono che l'HTO riduce la forza di trazione — surrogato della forza di distrazione — al sito di riparazione della radice meniscale posteriore, in particolare a 90° di flessione, e suggeriscono di limitare la flessione profonda sotto carico nella riabilitazione precoce dopo riparazione di una lesione radiale del segmento posteriore.",limits:"Modello animale, tempo zero, 10 campioni · nessuna misura di guarigione biologica né di esito clinico · non è specificamente la rifissazione transtibiale pull-out della radice (qui una lesione radiale del segmento posteriore riparata con sutura orizzontale, non un pull-out transosseo), quindi la trasferibilità diretta alla tua tecnica di root repair va verificata.",perte:"Aggiunge un tassello biomeccanico alla tensione T2b sul carico della riparazione meniscale: se operi un'osteotomia tibiale alta nello stesso tempo chirurgico di una riparazione della radice o di una grande lesione radiale posteriore, questo dato suggerisce che l'HTO stessa protegga meccanicamente il sito di sutura oltre i 60° di flessione — un argomento in più, insieme alla soglia di varo ≥5° già nota, per combinare le due procedure quando indicato, e per essere cauti sulla flessione profonda precoce anche quando l'osteotomia è stata eseguita."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Clinical Medicine",h:"Ansia e depressione preoperatorie pesano sulla protesi monocompartimentale",v:"Coorte di 203 ginocchia: ansia e depressione preoperatorie si associano a più progressione artrosica del compartimento laterale dopo protesi monocompartimentale, risultati dichiarati esplorativi.",ax:"Wang, Du, Cao",date:"set 2026",meta:"coorte retrospettiva osservazionale, 203 ginocchia, follow-up medio 70 mesi · [III]",pmid:'42739574',doi:'10.3390/jcm15176568',journal:"Journal of Clinical Medicine",authors:"Wang Z, Du M, Li Z, An S, Cao G, Huang Y",design:"Coorte retrospettiva osservazionale monocentrica (Beijing Jishuitan Hospital), database istituzionale prospettico, pazienti sottoposti a protesi monocompartimentale mediale (mUKA) fra marzo 2016 e dicembre 2020; stato psicologico preoperatorio con Hospital Anxiety and Depression Scale (HADS, soglia ≥8 per sottoscala = ansia/depressione, gruppo AD); esiti clinici (Oxford Knee Score, Forgotten Joint Score, Kujala) e radiografie standing a lunghezza intera seriali per allineamento coronale e grado Kellgren-Lawrence del compartimento laterale; regressione logistica uni e multivariabile per i fattori associati alla progressione artrosica laterale (LOP, definita come aumento ≥1 grado K/L).",pop:"203 ginocchia; 26 nel gruppo ansia/depressione (AD), 177 nel gruppo non-AD; follow-up radiografico disponibile in 99 ginocchia; follow-up medio 70 mesi.",results:"Al follow-up finale il gruppo AD ha OKS peggiore, minor miglioramento dell'OKS, e FJS e Kujala più bassi rispetto al gruppo non-AD. Progressione artrosica laterale (LOP) nel 26,3% delle ginocchia complessivamente, significativamente più frequente nel gruppo AD (60,0%) che nel gruppo non-AD (20,2%). All'analisi multivariabile, l'ansia/depressione preoperatoria resta associata a LOP dopo aggiustamento per le covariate prespecificate.",concl:"Gli autori concludono che l'ansia e/o la depressione preoperatorie si associano a una maggiore frequenza di progressione artrosica radiografica del compartimento laterale e a esiti riferiti dal paziente peggiori a medio termine dopo protesi monocompartimentale mediale, e definiscono i risultati esplorativi e generatori di ipotesi.",limits:"Gruppo AD piccolo (26 ginocchia) e follow-up radiografico disponibile solo in 99/203 ginocchia (48,8%) — possibile bias di selezione · disegno retrospettivo osservazionale, nessuna randomizzazione né misura standardizzata dell'aderenza riabilitativa · gli stessi autori dichiarano i risultati esplorativi, non confermatori.",perte:"Tocca direttamente la tua protesi monocompartimentale: uno screening psicologico preoperatorio semplice (HADS) potrebbe identificare i pazienti a rischio più alto di progressione del compartimento laterale nel medio termine, un'informazione utile nel counseling su rivalutazione periodica e aspettative di sopravvivenza dell'impianto — ma il campione piccolo del gruppo a rischio rende il dato ancora ipotesi da confermare, non un criterio operativo."}];
var SUGGQ=[{"k": "kol", "n": "Brian J. Cole", "w": "Midwest Orthopaedics at Rush, Chicago, Stati Uniti", "r": "Autore senior della revisione sistematica di oggi su impianto di cartilagine tritata autologa (AMCI) contro microfrattura e ACI (scheda 2): corrispondenza tecnica diretta con la tensione T4 sulla filiera AutoCart per il minced cartilage. Sostituisce la proposta invariata di Michael T. Hirschmann (15 settembre)."}];
var BRIEF_TEXT="Oggi sei lavori — una scheda in più del solito, perché il segnale di apertura era troppo rilevante per restare un breve. Una coorte di 623 pazienti operati di protesi monocompartimentale mostra che l'impianto costruito su misura per il singolo ginocchio non offre alcun vantaggio sugli esiti riferiti dal paziente rispetto a un impianto di serie, e si associa anzi a un tasso di revisione più alto a due anni (8,9% contro 3,8%), soprattutto per mobilizzazione asettica: un argomento di cautela contro l'idea che «personalizzato» significhi automaticamente «migliore». Una revisione sistematica di 41 studi mostra che il minced cartilage autologo tiene testa a microfrattura e impianto di condrociti, con un follow-up però ancora più corto — la prima risposta sistematica, anche se parziale, alla tensione T4 sul tuo minced cartilage. Due lavori toccano la tensione sul criterio di rientro dopo il crociato anteriore: una revisione di 47 studi mostra che il tendine quadricipitale non differisce da hamstring sulla capacità di saltare, e una coorte di 441 pazienti mostra che un danno alla cartilagine associato non impedisce il rientro allo sport, ma pesa sugli esiti soggettivi insieme al danno meniscale e all'età. Un esperimento di laboratorio su ginocchia porcine mostra per la prima volta che l'osteotomia tibiale alta riduce meccanicamente lo stress sulla sutura di una lesione radiale della radice meniscale, un tassello per la tensione T2b. Chiude una coorte di 203 ginocchia dove ansia e depressione preoperatorie si associano a più progressione artrosica dopo protesi monocompartimentale — risultati dichiarati esplorativi dagli stessi autori. Il raccoglitore notturno ha effettivamente funzionato, ma con un ritardo strutturale rispetto all'orario dichiarato: i dati più recenti disponibili risalgono al pomeriggio di ieri, non a stanotte in senso stretto — ho anticipato l'orario del cron per ridurre il rischio. Nessun richiamo nuovo entro la finestra di attualità, nessun cambiamento nei trial delle tensioni, nessun nuovo citante sui verdetti passati, nessuna ritrattazione nuova sui 240 PMID storici ricontrollati oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi sono sei schede invece delle solite cinque — una in più, perché il primo dato era troppo rilevante per restare un breve."}, {"chi": "B", "t": "Che cos'è successo?"}, {"chi": "A", "t": "Uno studio su 623 pazienti mostra che l'impianto di protesi parziale «su misura» per il singolo ginocchio non batte quello di serie: gli stessi risultati per il paziente, ma più revisioni a due anni."}, {"chi": "B", "t": "Quanto di più?"}, {"chi": "A", "t": "8,9% contro 3,8%, soprattutto per allentamento dall'osso. Un motivo per non dare per scontato che personalizzato significhi automaticamente migliore."}, {"chi": "B", "t": "E le altre schede?"}, {"chi": "A", "t": "Una revisione di 41 studi mostra che il tritato di cartilagine autologa tiene testa a tecniche più complesse — la prima risposta sistematica, anche se parziale, a una domanda che avevo aperto ad agosto."}, {"chi": "B", "t": "Cioè la tensione sul minced cartilage?"}, {"chi": "A", "t": "Esatto. Poi due lavori sul rientro allo sport dopo il crociato: uno mostra che l'innesto di tendine quadricipitale non svantaggia sulla capacità di saltare, l'altro che un danno alla cartilagine associato non impedisce di tornare a giocare."}, {"chi": "B", "t": "E il quinto?"}, {"chi": "A", "t": "Un esperimento di laboratorio: correggere l'asse della gamba con un'osteotomia riduce lo stress meccanico sulla riparazione di una lesione del menisco vicino al centro del ginocchio."}, {"chi": "B", "t": "E l'ultimo?"}, {"chi": "A", "t": "Ansia e depressione prima della protesi parziale si associano, in una coorte di 203 ginocchia, a più progressione artrosica dell'altra parte del ginocchio — ma gli stessi autori dicono che è un risultato da confermare, non ancora una regola."}, {"chi": "B", "t": "E il raccoglitore notturno, oggi ha funzionato?"}, {"chi": "A", "t": "Sì, con dati validi, ma sistematicamente in ritardo rispetto all'orario previsto: uso sempre i dati del pomeriggio prima, non quelli di stanotte in senso stretto. Ho anche anticipato l'orario del cron per ridurre il rischio. Nessun richiamo nuovo, nessuna ritrattazione sui 240 PMID storici ricontrollati oggi."}];
